// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.coreimport timber.log.Timberimport com.roshan.persona.common.IoDispatcherimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.sync.Muteximport kotlinx.coroutines.sync.withLockimport kotlinx.coroutines.withContext/** * NOUS — Model Manager (Module 6 v4 — Step 6.1, CRITICAL). * * Central registry + lifecycle manager for all Module 6 models. Implements the * v4 3-backend matrix (QNN + NeuroPilot + XNNPACK) + tiered quantization * (INT4 / INT2) + LMK survival protocol + A/B rollback. * * ## Responsibilities * * 1. **Backend selection** — pick the correct Omni-SLM variant at runtime *    based on [DeviceCapability] (SoC vendor + NPU + RAM tier). * 2. **Model loading** — load the Omni-SLM into RAM with the selected backend. *    Fall back to the next backend in the chain if the primary fails. * 3. **Model eviction** — release the Omni-SLM from RAM when the camera UI *    minimizes (LMK survival protocol, per v4 §"Critical Engineering Fix 3"). * 4. **A/B rollback** — if a new model version performs worse, roll back to *    the previous version via [ModelStore.rollback]. * 5. **Model verification** — SHA-256 + Ed25519 signature check before load. * * ## Why this matters * * v3 said "load the Omni-SLM with QNN delegate". That's wrong for 80% of * Android devices (MediaTek + Unisoc + Exynos don't have QNN). v4's * [ModelManager] picks the correct backend at runtime and falls back * gracefully — **no user left behind**. * * ## Production Wiring * * Wired via Hilt (Step 6.8 — VisionModule). The [OmniSlmDelegate] is bound * to [NativeOmniSlmDelegate] in production, [FakeOmniSlmDelegate] in tests. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Critical Engineering Fix 1: 3-Backend Matrix</a> */class ModelManager(    private val deviceCapabilityDetector: DeviceCapabilityDetector,    private val modelStore: ModelStore,    private val delegateFactory: OmniSlmDelegateFactory,    @IoDispatcher private val dispatcher: CoroutineDispatcher,) {    /** Cached device capability (computed once, reused). */    @Volatile    private var cachedCapability: DeviceCapability? = null    /** Currently-loaded Omni-SLM runtime (null if not loaded). */    @Volatile    private var currentRuntime: OmniSlmRuntime? = null    /** Mutex to prevent concurrent load/evict operations. */    private val runtimeMutex = Mutex()    /** Snapshot of the device capability. */    val capability: DeviceCapability        get() {            return cachedCapability ?: synchronized(this) {                cachedCapability ?: deviceCapabilityDetector.detect().also {                    cachedCapability = it                }            }        }    /**     * Get the Omni-SLM runtime, loading it if necessary.     *     * Implements the v4 3-backend matrix:     *     * ```     * 1. Detect device capability (SoC + NPU + RAM tier)     * 2. Resolve backend chain (e.g., [NEUROPILOT, OPENCL, XNNPACK])     * 3. For each backend in chain:     *    a. Check if model file exists + SHA-256 verified     *    b. Try to load via delegate     *    c. If success → return runtime     *    d. If fail → try next backend     * 4. All backends failed → return DisabledOmniSlmRuntime (v2 fallback)     * ```     *     * @return the loaded [OmniSlmRuntime], or a [DisabledOmniSlmRuntime] if     *         the device cannot run the Omni-SLM.     */    suspend fun getOmniSlmRuntime(): OmniSlmRuntime = runtimeMutex.withLock {        currentRuntime?.let {            if (it.isReady() || it.isDisabled) return@withLock it        }        val cap = capability        // Ultra-low RAM tier — return disabled runtime immediately.        if (cap.ramTier == RamTier.ULTRA) {            Timber.tag(TAG).w("Ultra-low RAM tier — Omni-SLM disabled, using v2 fallback.")            return@withLock DisabledOmniSlmRuntime(dispatcher).also { currentRuntime = it }        }        val backendChain = resolveBackendChain(cap)        val quantization = selectOmniSlmQuantization(cap)            ?: return@withLock DisabledOmniSlmRuntime(dispatcher).also { currentRuntime = it }        // Try each backend in the chain until one succeeds.        for (backend in backendChain) {            if (backend == ExecuTorchBackend.DISABLED) continue            val filename = omniSlmModelFilename(backend, quantization)            if (!modelStore.exists(filename)) {                Timber.tag(TAG).w("Model file $filename not found — skipping $backend.")                continue            }            Timber.tag(TAG).i("Attempting to load Omni-SLM with backend=$backend, quant=$quantization")            val delegate = delegateFactory.create(backend)            val runtime = OmniSlmRuntime(                delegate = delegate,                backend = backend,                quantization = quantization,                dispatcher = dispatcher,            )            val loaded = runtime.load()            if (loaded) {                Timber.tag(TAG).i("Omni-SLM loaded successfully with backend=$backend.")                currentRuntime = runtime                return@withLock runtime            } else {                Timber.tag(TAG).w("Backend $backend failed to load — trying next in chain.")            }        }        // All backends failed — return disabled runtime (v2 fallback).        Timber.tag(TAG).e("All backends failed — Omni-SLM disabled. Falling back to v2 stack.")        return@withLock DisabledOmniSlmRuntime(dispatcher).also { currentRuntime = it }    }    /**     * Evict the Omni-SLM from RAM (LMK survival protocol).     *     * Called when the camera UI minimizes (ActivityLifecycleCallback.onStop),     * per v4 §"Critical Engineering Fix 3: Android LMK Survival".     *     * The model file remains on disk for fast re-load via [getOmniSlmRuntime].     *     * @return true if eviction succeeded.     */    suspend fun evictOmniSlm(): Boolean = runtimeMutex.withLock {        val runtime = currentRuntime ?: return@withLock true        if (runtime.isDisabled) return@withLock true        val success = runtime.evict()        if (success) {            Timber.tag(TAG).i("Omni-SLM evicted from RAM (LMK survival protocol).")            // Don't null out currentRuntime — keep the delegate for fast re-load.        } else {            Timber.tag(TAG).w("Omni-SLM eviction failed — model still resident.")        }        success    }    /**     * Force a full reload of the Omni-SLM (used after A/B rollback).     */    suspend fun reloadOmniSlm(): Boolean = runtimeMutex.withLock {        currentRuntime?.evict()        currentRuntime = null        false  // Force getOmniSlmRuntime to re-load.    }.let {        getOmniSlmRuntime().isReady()    }    /**     * Roll back to the previous Omni-SLM model version.     *     * Used when A/B testing detects the new model performs worse than 5%     * degradation threshold (per v2 §"Issue 10: Model Update Rollback Strategy").     *     * @param backend the backend to roll back.     * @param quantization the quantization level.     * @return true if rollback succeeded.     */    suspend fun rollbackOmniSlm(        backend: ExecuTorchBackend,        quantization: OmniSlmQuantization,    ): Boolean = withContext(dispatcher) {        val filename = omniSlmModelFilename(backend, quantization)        val success = modelStore.rollback(filename)        if (success) {            Timber.tag(TAG).i("Rolled back Omni-SLM to previous version ($filename).")            reloadOmniSlm()        } else {            Timber.tag(TAG).w("No rollback available for $filename.")        }        success    }    /**     * Get the list of all stored model files (for Settings → Storage UI).     */    fun listStoredModels(): List<String> = modelStore.listModels()    /**     * Get the total on-disk size of all vision models (for Settings UI).     */    fun totalModelSizeBytes(): Long = modelStore.totalSizeBytes()    /**     * Clean up old rollback files older than 30 days (called by WorkManager daily).     */    suspend fun cleanupOldRollbacks(maxAgeDays: Int = 30): Int = withContext(dispatcher) {        modelStore.cleanupOldRollbacks(maxAgeDays)    }    /**     * Reset cached device capability (for tests).     */    fun resetCapabilityCache() {        cachedCapability = null    }    private companion object {        private const val TAG = "ModelManager"    }}// ──────────────────────────────────────────────────────────────────────────/** * Factory interface for creating [OmniSlmDelegate] instances. * * Production: [NativeOmniSlmDelegateFactory] creates delegates that wrap * `org.pytorch.executorch.Module`. Each backend (QNN, NeuroPilot, XNNPACK) * requires a different delegate configuration. * * Tests: [FakeOmniSlmDelegateFactory] returns the same [FakeOmniSlmDelegate] * regardless of backend (since tests don't actually load native models). */fun interface OmniSlmDelegateFactory {    /**     * Create a delegate for the given [backend].     *     * @param backend the target backend (QNN, NeuroPilot, OpenCL, XNNPACK).     * @return the delegate (or a NoOp delegate if backend is unavailable).     */    fun create(backend: ExecuTorchBackend): OmniSlmDelegate}
